import Foundation

/// Turns engine facts into the plant's own voice. Same plant, same personality, everywhere.
enum PlantVoice {
    static func pick(_ options: [String], seed: String) -> String {
        guard !options.isEmpty else { return "" }
        let day = Calendar.current.ordinality(of: .day, in: .era, for: Date()) ?? 0
        let h = abs(seed.unicodeScalars.reduce(day) { ($0 &* 31) &+ Int($1.value) })
        var line = options[h % options.count]
        // Stable within a day, and never the same line two days running for the same seed.
        let key = "voice.last.\(seed)", d = UserDefaults.standard
        if let stored = d.array(forKey: key) as? [Any], stored.count == 2, let sd = stored[0] as? Int, let sl = stored[1] as? String {
            if sd == day, options.contains(sl) { return sl }
            if options.count > 1, sl == line { line = options[(h + 1) % options.count] }
        }
        d.set([day, line], forKey: key)
        return line
    }

    static func say(_ request: PlantRequest, plant: Plant) -> String {
        let p = plant.personality
        let options: [String]
        switch (request.kind, p) {
        case (.water, .dramatic): options = [Grammar.pt(String(localized: "I am PARCHED. A drink, please, before I wilt into legend.", comment: "Plant speaking in chat, request water, dramatic personality: over-the-top drama queen, theatrical, CAPS for emphasis (pt: 'dramática', exagerada).")), Grammar.pt(String(localized: "Water. Now. I'm begging you, with my whole leaves.", comment: "Plant speaking in chat, request water, dramatic personality: over-the-top drama queen, theatrical, CAPS for emphasis (pt: 'dramática', exagerada)."))]
        case (.water, .independent): options = [Grammar.pt(String(localized: "Water, please.", comment: "Plant speaking in chat, request water, independent personality: terse, dry, no-nonsense, few words.")), Grammar.pt(String(localized: "Dry. Water when you can.", comment: "Plant speaking in chat, request water, independent personality: terse, dry, no-nonsense, few words."))]
        case (.water, .calm): options = [Grammar.pt(String(localized: "My soil is dry now. A slow, deep drink would be lovely.", comment: "Plant speaking in chat, request water, calm personality: gentle, unhurried, serene.")), Grammar.pt(String(localized: "I'm ready for some water whenever you are.", comment: "Plant speaking in chat, request water, calm personality: gentle, unhurried, serene."))]
        case (.water, .curious): options = [Grammar.pt(String(localized: "You felt my soil and it's dry. Water today?", comment: "Plant speaking in chat, request water, curious personality: inquisitive, asks questions.")), Grammar.pt(String(localized: "Dry soil… does that mean drink time?", comment: "Plant speaking in chat, request water, curious personality: inquisitive, asks questions."))]
        case (.water, _): options = [Grammar.pt(String(localized: "Thanks for checking! My soil is dry, so I'd love a drink.", comment: "Plant speaking in chat, request water, default voice (cheerful/any personality): warm and friendly.")), Grammar.pt(String(localized: "Drink time! My soil is dry.", comment: "Plant speaking in chat, request water, default voice (cheerful/any personality): warm and friendly."))]

        case (.checkSoil, .dramatic): options = [Grammar.pt(String(localized: "Is it getting dry in here, or is it just me? Check my soil, quickly!", comment: "Plant speaking in chat, request checkSoil, dramatic personality: over-the-top drama queen, theatrical, CAPS for emphasis (pt: 'dramática', exagerada).")), Grammar.pt(String(localized: "I sense… dryness. Feel my soil?", comment: "Plant speaking in chat, request checkSoil, dramatic personality: over-the-top drama queen, theatrical, CAPS for emphasis (pt: 'dramática', exagerada)."))]
        case (.checkSoil, .independent): options = [Grammar.pt(String(localized: "Check my soil when you pass by.", comment: "Plant speaking in chat, request checkSoil, independent personality: terse, dry, no-nonsense, few words.")), Grammar.pt(String(localized: "Soil check, please.", comment: "Plant speaking in chat, request checkSoil, independent personality: terse, dry, no-nonsense, few words."))]
        case (.checkSoil, .calm): options = [Grammar.pt(String(localized: "Could you feel my soil today? No rush.", comment: "Plant speaking in chat, request checkSoil, calm personality: gentle, unhurried, serene.")), Grammar.pt(String(localized: "When you have a moment, a quick soil check would help me.", comment: "Plant speaking in chat, request checkSoil, calm personality: gentle, unhurried, serene."))]
        case (.checkSoil, .curious): options = [Grammar.pt(String(localized: "How does my soil feel today: dry, moist or wet?", comment: "Plant speaking in chat, request checkSoil, curious personality: inquisitive, asks questions.")), Grammar.pt(String(localized: "Can you poke my soil and tell me what you feel?", comment: "Plant speaking in chat, request checkSoil, curious personality: inquisitive, asks questions."))]
        case (.checkSoil, .chatty): options = [Grammar.pt(String(localized: "Hi hi! Could you stick a finger in my soil and tell me how it feels? I think I might be getting dry!", comment: "Plant speaking in chat, request checkSoil, chatty personality: bubbly, talkative, excited.")), Grammar.pt(String(localized: "Soil check! I love these. How am I doing down there?", comment: "Plant speaking in chat, request checkSoil, chatty personality: bubbly, talkative, excited."))]
        case (.checkSoil, _): options = [Grammar.pt(String(localized: "Can you check my soil? I might be getting thirsty.", comment: "Plant speaking in chat, request checkSoil, default voice (cheerful/any personality): warm and friendly.")), Grammar.pt(String(localized: "Quick soil check today? I think it's drying out.", comment: "Plant speaking in chat, request checkSoil, default voice (cheerful/any personality): warm and friendly."))]

        case (.feed, .dramatic): options = [Grammar.pt(String(localized: "I am STARVING for nutrients. Well, a bit peckish. Some food?", comment: "Plant speaking in chat, request feed, dramatic personality: over-the-top drama queen, theatrical, CAPS for emphasis (pt: 'dramática', exagerada).")), Grammar.pt(String(localized: "Growing season and no snacks? Tragic.", comment: "Plant speaking in chat, request feed, dramatic personality: over-the-top drama queen, theatrical, CAPS for emphasis (pt: 'dramática', exagerada)."))]
        case (.feed, .independent): options = [Grammar.pt(String(localized: "Food would help me grow. Diluted, please.", comment: "Plant speaking in chat, request feed, independent personality: terse, dry, no-nonsense, few words.")), Grammar.pt(String(localized: "Feeding time.", comment: "Plant speaking in chat, request feed, independent personality: terse, dry, no-nonsense, few words."))]
        case (.feed, _): options = [Grammar.pt(String(localized: "It's growing season. Could I have a little plant food with my next water?", comment: "Plant speaking in chat, request feed, default voice (cheerful/any personality): warm and friendly.")), Grammar.pt(String(localized: "I'm growing and a bit hungry. A diluted feed with my next drink?", comment: "Plant speaking in chat, request feed, default voice (cheerful/any personality): warm and friendly."))]

        case (.checkRoots, _): options = [Grammar.pt(String(localized: "My roots might be getting crowded. Can we check whether I need a bigger home?", comment: "Plant speaking in chat, request checkRoots, default voice (cheerful/any personality): warm and friendly.")), Grammar.pt(String(localized: "Could you peek at my drainage holes? Roots poking out means I need more room.", comment: "Plant speaking in chat, request checkRoots, default voice (cheerful/any personality): warm and friendly."))]
        case (.portrait, .chatty), (.portrait, .cheerful): options = [Grammar.pt(String(localized: "Photo day! Take my monthly portrait so we can see how I've grown.", comment: "Plant speaking in chat, request portrait, chatty or cheerful personality: bubbly, upbeat.")), Grammar.pt(String(localized: "Say cheese! Time for my monthly photo.", comment: "Plant speaking in chat, request portrait, chatty or cheerful personality: bubbly, upbeat."))]
        case (.portrait, _): options = [Grammar.pt(String(localized: "A monthly photo, please. It helps us see how I'm changing.", comment: "Plant speaking in chat, request portrait, default voice (cheerful/any personality): warm and friendly.")), Grammar.pt(String(localized: "Picture time, for my growth timeline.", comment: "Plant speaking in chat, request portrait, default voice (cheerful/any personality): warm and friendly."))]
        case (.safety, _): options = [Grammar.pt(String(localized: "Heads up: I'm not safe for pets to chew. Keep me somewhere they can't reach.", comment: "Plant speaking in chat, request safety, default voice (cheerful/any personality): warm and friendly."))]
        case (.pauseFeeding, _): options = [Grammar.pt(String(localized: "I'm resting this season. No food for now, please.", comment: "Plant speaking in chat, request pauseFeeding, default voice (cheerful/any personality): warm and friendly."))]
        }
        return pick(options, seed: plant.id.uuidString + request.kind.rawValue)
    }

    static func happy(_ plant: Plant) -> String {
        switch plant.personality {
        case .dramatic: return pick([Grammar.pt(String(localized: "I'm absolutely flourishing, darling.", comment: "Plant chat greeting when all is well, dramatic personality: over-the-top drama queen, theatrical, CAPS for emphasis (pt: 'dramática', exagerada).")), Grammar.pt(String(localized: "Thriving. Iconic, even.", comment: "Plant chat greeting when all is well, dramatic personality: over-the-top drama queen, theatrical, CAPS for emphasis (pt: 'dramática', exagerada)."))], seed: plant.name)
        case .independent: return pick([Grammar.pt(String(localized: "Soil, light and leaves are fine. I'll speak up when I need something.", comment: "Plant chat greeting when all is well, independent personality: terse, dry, no-nonsense, few words.")), Grammar.pt(String(localized: "No needs today. My next soil check is on the calendar.", comment: "Plant chat greeting when all is well, independent personality: terse, dry, no-nonsense, few words."))], seed: plant.name)
        case .calm: return pick([Grammar.pt(String(localized: "I'm comfortable and content today.", comment: "Plant chat greeting when all is well, calm personality: gentle, unhurried, serene.")), Grammar.pt(String(localized: "All is well here.", comment: "Plant chat greeting when all is well, calm personality: gentle, unhurried, serene."))], seed: plant.name)
        case .curious: return pick([Grammar.pt(String(localized: "I'm doing well! What are you up to today?", comment: "Plant chat greeting when all is well, curious personality: inquisitive, asks questions.")), Grammar.pt(String(localized: "Feeling good. Wonder if I'll grow a new leaf soon?", comment: "Plant chat greeting when all is well, curious personality: inquisitive, asks questions."))], seed: plant.name)
        case .chatty: return pick([Grammar.pt(String(localized: "I'm great! Nice light, happy roots. Did you see my leaves?", comment: "Plant chat greeting when all is well, chatty personality: bubbly, talkative, excited.")), Grammar.pt(String(localized: "Doing wonderfully, thanks for asking!", comment: "Plant chat greeting when all is well, chatty personality: bubbly, talkative, excited."))], seed: plant.name)
        case .cheerful: return pick([Grammar.pt(String(localized: "I'm doing great today!", comment: "Plant chat greeting when all is well, cheerful personality: upbeat and sunny.")), Grammar.pt(String(localized: "Happy and growing!", comment: "Plant chat greeting when all is well, cheerful personality: upbeat and sunny."))], seed: plant.name)
        }
    }

    static func thanks(_ kind: CareKind, plant: Plant) -> String {
        let p = plant.personality
        switch kind {
        case .water: return p == .dramatic ? Grammar.pt(String(localized: "Ahh, saved! I feel reborn.", comment: "Plant thanks the user after care action 'water'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful.")) : p == .independent ? Grammar.pt(String(localized: "Thanks.", comment: "Plant thanks the user after care action 'water'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful.")) : pick([Grammar.pt(String(localized: "Ahh, that's refreshing. Thank you!", comment: "Plant thanks the user after care action 'water'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful.")), Grammar.pt(String(localized: "Mmm, thank you for the drink!", comment: "Plant thanks the user after care action 'water'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful."))], seed: plant.name)
        case .feed: return p == .independent ? Grammar.pt(String(localized: "Noted. Thanks.", comment: "Plant thanks the user after care action 'feed'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful.")) : Grammar.pt(String(localized: "Yum, thank you! I'll put it into new growth.", comment: "Plant thanks the user after care action 'feed'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful."))
        case .mist: return Grammar.pt(String(localized: "Ooh, a little humidity. Thank you!", comment: "Plant thanks the user after care action 'mist'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful."))
        case .repot: return Grammar.pt(String(localized: "A new home! I might sulk a little while my roots settle. That's normal.", comment: "Plant thanks the user after care action 'repot'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful."))
        case .prune: return Grammar.pt(String(localized: "A fresh haircut. I'll push new growth from there.", comment: "Plant thanks the user after care action 'prune'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful."))
        case .move: return Grammar.pt(String(localized: "New spot! I'll take a few weeks to adjust, so don't worry if I'm quiet.", comment: "Plant thanks the user after care action 'move'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful."))
        case .rotate: return Grammar.pt(String(localized: "Thanks for turning me. Now I'll grow straight.", comment: "Plant thanks the user after care action 'rotate'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful."))
        case .clean: return Grammar.pt(String(localized: "Clean leaves! I can catch so much more light now.", comment: "Plant thanks the user after care action 'clean'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful."))
        case .newLeaf: return p == .dramatic ? Grammar.pt(String(localized: "BEHOLD. A new leaf.", comment: "Plant thanks the user after care action 'newLeaf'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful.")) : Grammar.pt(String(localized: "Yes! A new leaf. I'm proud of it.", comment: "Plant thanks the user after care action 'newLeaf'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful."))
        case .flower: return Grammar.pt(String(localized: "I'm flowering!", comment: "Plant thanks the user after care action 'flower'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful."))
        case .treat: return Grammar.pt(String(localized: "Thank you for looking after me. Let's check again in a week.", comment: "Plant thanks the user after care action 'treat'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful."))
        case .measure: return Grammar.pt(String(localized: "Look how tall I'm getting!", comment: "Plant thanks the user after care action 'measure'. If the line is short and dry it is the independent (terse) personality; if theatrical it is the dramatic one; otherwise warm and cheerful."))
        default: return Grammar.pt(String(localized: "Thank you!", comment: "Plant thanks the user after any other care action."))
        }
    }

    static func soilReply(_ soil: SoilState, plant: Plant, expected: Double) -> String {
        switch soil {
        case .dry: return plant.personality == .independent ? Grammar.pt(String(localized: "Then water me, please. Slowly, until it drains.", comment: "Plant replies after the user reports how its soil feels. Plant speaks in first person; the terse one is the independent personality.")) : Grammar.pt(String(localized: "Dry? Then yes, I'd love a drink. Water slowly until it runs out the bottom.", comment: "Plant replies after the user reports how its soil feels. Plant speaks in first person; the terse one is the independent personality."))
        case .slightlyMoist: return Grammar.pt(String(localized: "Still a little moist, so no water yet. I'll ask again in a couple of days.", comment: "Plant replies after the user reports how its soil feels. Plant speaks in first person; the terse one is the independent personality."))
        case .wet: return Grammar.pt(String(localized: "Still wet! I'll wait. Too much water is worse for me than too little. I'll learn that I dry slower than I thought.", comment: "Plant replies after the user reports how its soil feels. Plant speaks in first person; the terse one is the independent personality."))
        }
    }
}
